-- Provisional cognitive ratings; never convert the legacy coarse difficulty.
-- Ratings are tied to immutable package identity, independently of personal reflections.
CREATE TABLE problem_thinking_profile (
 problem_version VARCHAR(80) PRIMARY KEY REFERENCES problem_version(id) ON DELETE CASCADE,
 package_sha256 VARCHAR(64) NOT NULL,
 layer INTEGER NOT NULL CHECK (layer BETWEEN 1 AND 9),
 insight INTEGER NOT NULL CHECK (insight BETWEEN 1 AND 5),
 implementation INTEGER NOT NULL CHECK (implementation BETWEEN 1 AND 5),
 edge_cases INTEGER NOT NULL CHECK (edge_cases BETWEEN 1 AND 5),
 rationale VARCHAR(300) NOT NULL,
 source VARCHAR(24) NOT NULL CHECK (source IN ('CURATED_ESTIMATE','AUTHOR_ESTIMATE')),
 updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
